import manifest from './lastmod.generated.json';

// Last-change dates (YYYY-MM-DD) per content file, generated by scripts/generate-lastmod.mjs from
// the git history. They drive the sitemap <lastmod>, the JSON-LD dateModified and the visible
// "Last updated" line, so they move only when a page's content really changes.
//
// A ficha's own `last_updated` field is only a fallback for a file that is not in the manifest yet:
// it is hand-entered and not reliable (80 fichas had it later than the last commit that touched
// them), so it never overrides the git date.
const dates = manifest as Record<string, string>;

function latest(values: Array<string | undefined>): string | null {
  const real = values.filter((v): v is string => Boolean(v));
  return real.length ? real.reduce((a, b) => (a > b ? a : b)) : null;
}

function latestUnder(prefix: string): string | null {
  return latest(Object.entries(dates).filter(([file]) => file.startsWith(prefix)).map(([, d]) => d));
}

export function getCastleLastModified(country: string, slug: string, lastUpdatedField?: string): string | null {
  return dates[`data/castles/${country}/${slug}.json`] ?? lastUpdatedField ?? null;
}

export function getTourLastModified(country: string, slug: string): string | null {
  return dates[`data/tours/${country}/${slug}.json`] ?? null;
}

export function getRouteLastModified(id: string): string | null {
  return dates[`data/routes/${id}.json`] ?? null;
}

export function getGuideLastModified(id: string): string | null {
  return dates[`data/guides/${id}.json`] ?? null;
}

export function getStaticPageLastModified(sourceFile: string): string | null {
  return dates[sourceFile] ?? null;
}

/** Newest date among a country's castle fichas (used by the country hubs). */
export function getCastlesCountryLastModified(country: string): string | null {
  return latestUnder(`data/castles/${country}/`);
}

export function getAllCastlesLastModified(): string | null {
  return latestUnder('data/castles/');
}

/** Newest date among a country's tours (used by the /tours/<country> hubs). */
export function getToursCountryLastModified(country: string): string | null {
  return latestUnder(`data/tours/${country}/`) ?? latestUnder('data/tours/');
}

export function getAllToursLastModified(): string | null {
  return latestUnder('data/tours/');
}

export function getAllRoutesLastModified(): string | null {
  return latestUnder('data/routes/');
}

export function getAllGuidesLastModified(): string | null {
  return latestUnder('data/guides/');
}

/** Newest date across every castle and tour (home page). */
export function getSiteLastModified(): string | null {
  return latest([getAllCastlesLastModified() ?? undefined, getAllToursLastModified() ?? undefined]);
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

/** "2026-11-08" -> "November 2026" */
export function formatMonthYear(isoDate: string): string {
  const [year, month] = isoDate.split('-');
  return `${MONTHS[Number(month) - 1]} ${year}`;
}
